import{_ as l,l as r,o as e,c as n,v as t,p as s,x as o,d as h,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"刻蚀模型校准","description":"","frontmatter":{"title":"刻蚀模型校准","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/etch-model-calibration.md","filePath":"litho/etch-model-calibration.md","lastUpdated":1789023840000}'),c={name:"litho/etch-model-calibration.md"};function p(A,a,m,_,I,B){const i=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="刻蚀模型校准" tabindex="-1">刻蚀模型校准 <a class="header-anchor" href="#刻蚀模型校准" aria-label="Permalink to &quot;刻蚀模型校准&quot;">​</a></h1><div class="epigraph"><p>ADI 贴目标不等于硅上贴目标；刻蚀核要在 AEI 上单独拟合，换腔体就换版本。</p><footer>—— 对照紧凑刻蚀模型、ADI/AEI 成对计量与负载效应的产线通称</footer></div><p><a href="/litho/3d-resist-model">上一课</a>承认胶是三维的。缺口是下一跳：等离子体把胶形变成硬掩模/介质/硅形，偏置随密度与深宽比变。本课钉刻蚀模型校准。<a href="/litho/etch-in-opc">刻蚀进 OPC</a> 已说明为何要进迭代；这里补怎么标定。全芯片算力，留给[下一课](/litho/full-chip-simulation-cost）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>紧凑刻蚀模型吃显影多边形，吐刻蚀后边：短程偏置 + 密度核 + 有时取向。校准数据必须是<strong>同一部位</strong>的 ADI 与 AEI，否则光学残差会被刻蚀项吞掉。ARDE、微负载、大面积负载尺度不同，一个核半径不够——与 PEC 多层核同构。</p><p>缺口是<strong>AEI 协议</strong>，不是再讲 RIE 化学。把「经验 etch bias 表」当校准完成，二维邻域仍会在 SRAM–逻辑边界爆。</p><h3 id="换配方即新模型" tabindex="-1">换配方即新模型 <a class="header-anchor" href="#换配方即新模型" aria-label="Permalink to &quot;换配方即新模型&quot;">​</a></h3><p>功率、气体、过刻、硬掩模材料一变，核作废。OPC 版本号要含刻蚀工艺 id。APC 以后可以微调平均偏置，但不能当全核重标定。</p><p><span class="marginnote">最终签核写清轮廓：ADI、AEI 还是电学。PW-band 只含 ADI 时，窗口角可能在转印里被吃掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验：密度矩阵、通过节距、二维、深宽比变化（不同开口）。计量：CD-SEM AEI、有时 TEM 截面。拟合：与胶分两阶段，先锁 ADI 再锁刻蚀。保持集含产品 clips。与 <a href="/litho/etch-bias-opc-loop">etch bias OPC 回环</a> 后课（集成门）的关系：本课是模型； fab 回环是用在线 AEI 去更新偏置——控制层，不是再建一个物理腔。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>中性基消耗随开口面积变（负载），离子角分布随深宽比变（ARDE），聚合物在侧壁沉积随局部通量变。紧凑核是这些效应在边法向上的投影，不是 PIC 粒子模拟。梯度若要穿过核，核必须对 jog 足够光滑，否则 OPC 振荡。</p>',13)),(e(),s(E,null,{default:o(()=>[d(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADI%5B%22%E6%98%BE%E5%BD%B1%E8%BE%B9%22%5D%20--%3E%20KERNEL%5B%22%E5%AF%86%E5%BA%A6%20%2B%20%E7%9F%AD%E7%A8%8B%E5%88%BB%E8%9A%80%E6%A0%B8%22%5D%0A%20%20KERNEL%20--%3E%20AEI%5B%22%E5%88%BB%E8%9A%80%E5%90%8E%E8%BE%B9%22%5D%0A%20%20PAIR%5B%22%E6%88%90%E5%AF%B9%20ADI%2FAEI%20%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20FIT%5B%22%E6%8B%9F%E5%90%88%E6%A0%B8%22%5D%0A%20%20FIT%20--%3E%20KERNEL%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>紧凑刻蚀 ≠ 等离子体第一性原理。不把某腔体的 nm/min 写成宇宙速率。校准不覆盖等离子体不稳定与颗粒。</p><p>后课默认：前向链光学–胶–刻蚀都有可调用核；下一课问全芯片扫一遍要多少算力，从而 LRC 只能抽样。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>刻蚀核在成对 ADI/AEI 上单独拟合，与胶项分家。</li><li>负载多层尺度；换腔体换版本。</li><li>签核轮廓定义必须写进模型合同。</li><li>出处：紧凑刻蚀模型与负荷效应产线通称；计算光刻 OPC–刻蚀链。</li></ul>',5))])}const b=l(c,[["render",p]]);export{f as __pageData,b as default};
